:root { font-family: system-ui, sans-serif; color: #182c3c; background: #f4f7fa; }
body { margin: 0; }
main { max-width: 720px; margin: 64px auto; padding: 28px; }
h1 { font-size: 2.3rem; margin: 0 0 32px; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 10px; }
.create-controls { display: flex; gap: 12px; }
input, textarea { flex: 1; min-width: 0; padding: 12px; border: 1px solid #788b9a; border-radius: 6px; font: inherit; }
button { padding: 12px 18px; border: 1px solid #245479; border-radius: 6px; background: #245479; color: white; font: inherit; cursor: pointer; }
button:hover { background: #173f5e; }
button:disabled { opacity: .6; cursor: wait; }
button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible { outline: 3px solid #c27818; outline-offset: 3px; }
[role="alert"] { color: #a02222; }
#projects { margin-top: 30px; }
.project-row, .task-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; margin: 12px 0; padding: 18px; background: white; border: 1px solid #d2dce4; border-radius: 8px; }
