.project-row button { flex-shrink: 0; }
#back { margin-bottom: 28px; }
section[aria-label="Tasks"] { margin-top: 28px; }
.task-filter, .project-filter { margin-top: 24px; }
#due-range { margin-top: 24px; }
.search-form { margin-top: 24px; }
#due-from { margin-bottom: 16px; }
.project-row { flex-wrap: wrap; }
select { padding: 10px; font: inherit; border: 1px solid #788b9a; border-radius: 6px; background: white; }
.task-row { flex-wrap: wrap; }
.task-row input[type="checkbox"] { flex: none; width: 20px; height: 20px; cursor: pointer; }
.task-rename, .task-due-date, .task-notes, .task-move { flex-basis: 100%; min-width: 0; }
.task-notes textarea { display: block; box-sizing: border-box; width: 100%; margin-bottom: 12px; resize: vertical; }
@media (max-width: 480px) { main { margin: 20px auto; padding: 20px; } .create-controls { flex-direction: column; } .project-row { align-items: flex-start; flex-direction: column; } }
